INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Brave Now', 'When I was little, I used to be afraid of almost everything. I was afraid of the dark, afraid of dogs, and even afraid of speaking in front of the class. My hands would shake and my face would turn red. My mother always told me, "Everyone feels scared sometimes. Being brave does not mean you have no fear. It means you keep going even when you are afraid." Her words stayed in my mind. Little by little, I tried to face my fears. I started by reading a poem aloud at home, then in front of my family, and finally in class. Last week, I gave a speech to the whole school. I was still a little nervous, but I did it. I am not the shy child I used to be.', '记叙文', 133, '[{"q": "What is the passage mainly about?", "answer": "A", "options": ["How the writer became braver over time.", "How to write a poem.", "Why dogs are scary.", "The writer''s favorite class."], "explanation": "主旨:讲述作者如何逐渐克服恐惧变勇敢"}, {"q": "What did the writer use to be afraid of?", "answer": "C", "options": ["Tests and homework.", "Water and heights.", "The dark, dogs, and speaking in class.", "Cars and trains."], "explanation": "原文:afraid of the dark, dogs, and speaking in front of the class"}, {"q": "According to the mother, what does being brave mean?", "answer": "C", "options": ["Never feeling any fear.", "Asking others for help.", "Keeping going even when you are afraid.", "Avoiding all danger."], "explanation": "原文:keep going even when you are afraid"}, {"q": "How did the writer first practice facing fear?", "answer": "A", "options": ["By reading a poem aloud at home.", "By playing with dogs.", "By turning off the lights.", "By giving a school speech."], "explanation": "原文:started by reading a poem aloud at home"}, {"q": "What can we learn about the writer now?", "answer": "A", "options": ["The writer is much braver than before.", "The writer hates speaking.", "The writer is still very shy.", "The writer is afraid of school."], "explanation": "推断:结尾 I am not the shy child I used to be"}]'::jsonb, '[]'::jsonb, 3, '9', 'U4');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'A Class Reunion', 'Anna: Is that you, Ben? You look so different! You used to be really short, didn''t you?
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Why People Change', 'Why do people change as they grow up? Scientists say there are many reasons. First, our bodies change. A child who used to be the shortest in class may become the tallest as a teenager. Second, our interests change. Many people who used to hate vegetables enjoy them as adults. Third, our experiences shape us. A student who used to be afraid of speaking may become confident after joining a club or winning a competition. Change is a normal part of life. It does not happen overnight; it happens slowly, day by day. The important thing is not to compare yourself with others, but to notice how far you have come from the person you used to be.', '说明文', 118, '[{"q": "What is the main idea of the passage?", "answer": "B", "options": ["Clubs are important for students.", "People change as they grow up, for several reasons.", "Vegetables are good for health.", "Tall people are more confident."], "explanation": "主旨:解释人成长中为何会变化"}, {"q": "Which is NOT a reason for change mentioned?", "answer": "C", "options": ["Our interests change.", "Our experiences shape us.", "The weather where we live.", "Our bodies change."], "explanation": "原文给出身体/兴趣/经历三条,未提天气"}, {"q": "How does change usually happen, according to the text?", "answer": "A", "options": ["Slowly, day by day.", "Only in childhood.", "Suddenly, overnight.", "Only after winning a prize."], "explanation": "原文:It does not happen overnight; it happens slowly"}, {"q": "What does the writer advise readers to do?", "answer": "D", "options": ["Stay the same forever.", "Compare themselves with others.", "Avoid joining clubs.", "Notice how far they have come."], "explanation": "原文:not to compare… but to notice how far you have come"}, {"q": "What does the word \"shape\" mean in the passage?", "answer": "C", "options": ["To cut into pieces.", "To clean carefully.", "To influence or change.", "To draw a picture."], "explanation": "猜词:experiences shape us = 经历塑造/影响我们"}]'::jsonb, '[]'::jsonb, 3, '9', 'U4');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'A Letter to My Younger Self', 'Dear younger me, I know you are scared right now. You are afraid of the dark, afraid of making mistakes, and afraid that others will laugh at you. I want you to know that things will get better. You used to think you were not good enough, but you are wrong. In a few years, you will stand on a stage and sing in front of hundreds of people. You won''t believe it now, but it is true. The shy, quiet child you are today will grow into someone brave and kind. So please, don''t give up. Take small steps every day. Be patient with yourself. The fears that feel so big now will one day feel very small. With love, your future self.', '书信', 124, '[{"q": "Who is the letter written to?", "answer": "A", "options": ["The writer''s younger self.", "The writer''s best friend.", "The writer''s teacher.", "A famous singer."], "explanation": "原文:Dear younger me / your future self"}, {"q": "What did the younger self use to think?", "answer": "B", "options": ["That the writer was the best.", "That the writer was not good enough.", "That the writer would be a doctor.", "That school was easy."], "explanation": "原文:used to think you were not good enough"}, {"q": "What will the younger self do in a few years?", "answer": "B", "options": ["Move to another country.", "Sing on a stage in front of many people.", "Become a teacher.", "Win a sports match."], "explanation": "原文:stand on a stage and sing in front of hundreds"}, {"q": "What advice does the writer give?", "answer": "C", "options": ["Compare yourself with others.", "Give up when it is hard.", "Take small steps and be patient.", "Stay afraid of the dark."], "explanation": "原文:Take small steps every day. Be patient"}, {"q": "What is the tone of the letter?", "answer": "D", "options": ["Angry and cold.", "Sad and hopeless.", "Funny and silly.", "Encouraging and warm."], "explanation": "推断:全文鼓励温暖语气"}]'::jsonb, '[]'::jsonb, 3, '9', 'U4');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Is Change Always Good?', 'Most people agree that change can be a good thing. A shy child who becomes confident, or a lazy student who learns to work hard — these are changes we admire. However, not all change is good. Some people who used to be kind become selfish when they get rich or famous. Some who used to love reading stop because they spend all their time on their phones. So change itself is not always good or bad; what matters is the direction. We should welcome changes that make us better people, and be careful about changes that take us away from who we want to be. The goal is not just to change, but to grow.', '议论文', 116, '[{"q": "What is the main argument of the passage?", "answer": "A", "options": ["Change is not always good; the direction matters.", "All change is bad.", "All change is good.", "People should never change."], "explanation": "主旨:变化好坏取决于方向"}, {"q": "Which is given as an example of bad change?", "answer": "A", "options": ["Kind people becoming selfish when rich.", "A shy child becoming confident.", "A lazy student working hard.", "A child learning to read."], "explanation": "原文:used to be kind become selfish when they get rich"}, {"q": "Why do some people stop reading, according to the text?", "answer": "C", "options": ["They become teachers.", "They move away.", "They spend all their time on phones.", "They lose their books."], "explanation": "原文:stop because they spend all their time on their phones"}, {"q": "What kind of change does the writer support?", "answer": "B", "options": ["Any change at all.", "Change that makes us better people.", "Change that makes us famous.", "Change that makes us rich."], "explanation": "原文:welcome changes that make us better people"}, {"q": "What does the writer mean by \"not just to change, but to grow\"?", "answer": "B", "options": ["Change is always easy.", "We should change in a positive direction.", "Growing is impossible.", "We should never change."], "explanation": "推断:成长=向好的方向变化"}]'::jsonb, '[]'::jsonb, 3, '9', 'U4');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Youth Club Notice: ''The New Me'' Sharing Day', 'GREENWOOD YOUTH CLUB invites you to our ''The New Me'' Sharing Day! Have you changed a lot in the past few years? Come and share your story! WHEN: Saturday, May 18th, 2:00 p.m. - 4:00 p.m. WHERE: Club Hall, 2nd floor. WHAT TO DO: Tell us in three minutes how you used to be and how you have changed. You can bring old photos! PRIZES: The three most inspiring stories will win a free book of their choice. SIGN UP: Write your name on the list outside Room 201 before May 15th. Everyone is welcome — whether you used to be shy, afraid, or just very different. We believe every story can inspire someone else!', '应用文', 115, '[{"q": "What is the main purpose of this notice?", "answer": "D", "options": ["To sell old photos.", "To advertise a bookshop.", "To start a reading class.", "To invite young people to share how they have changed."], "explanation": "应用文目的:邀请分享成长变化"}, {"q": "When does the event take place?", "answer": "B", "options": ["Sunday morning.", "Saturday, May 18th, 2:00-4:00 p.m.", "Friday, May 15th, all day.", "May 201st."], "explanation": "原文:Saturday, May 18th, 2:00 p.m. - 4:00 p.m."}, {"q": "What can a participant bring?", "answer": "C", "options": ["A pet dog.", "Food and drinks.", "Old photos.", "A musical instrument."], "explanation": "原文:You can bring old photos"}, {"q": "What do the three best stories win?", "answer": "D", "options": ["A free trip.", "Money.", "A trophy.", "A free book of their choice."], "explanation": "原文:win a free book of their choice"}, {"q": "How does one sign up?", "answer": "B", "options": ["Just show up on the day.", "Write your name on the list outside Room 201 before May 15th.", "Send an email.", "Call the club."], "explanation": "原文:Write your name on the list outside Room 201 before May 15th"}]'::jsonb, '[]'::jsonb, 3, '9', 'U4');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U4', 'Afraid of the Dark', 'When I was six, I used to be afraid of the (1)____. Every night, I asked my mother to leave a light (2)____. I believed there were monsters under my bed. One evening, my father sat down and (3)____ to me kindly. He said, "The dark is not (4)____. It is just a room without light." To help me, he gave me a small (5)____ to hold at night. Slowly, I began to feel (6)____. I learned to turn off the light by (7)____. Now I am twelve, and I am not afraid (8)____ more. Looking back, I think my father (9)____ me an important lesson: most fears are not (10)____, and we can face them one step at a time.', 121, 3, '[{"q": "1", "answer": "D", "options": ["sky", "light", "day", "dark"], "explanation": "怕黑,afraid of the dark"}, {"q": "2", "answer": "A", "options": ["on", "out", "off", "up"], "explanation": "开着灯 leave a light on"}, {"q": "3", "answer": "A", "options": ["talked", "shouted", "listened", "looked"], "explanation": "talk to me 跟我谈"}, {"q": "4", "answer": "C", "options": ["happy", "easy", "scary", "funny"], "explanation": "黑暗不可怕 not scary"}, {"q": "5", "answer": "B", "options": ["ball", "toy", "map", "book"], "explanation": "给个玩具拿着,后文hold at night"}, {"q": "6", "answer": "B", "options": ["afraid", "safer", "tired", "worse"], "explanation": "渐渐感到更安全 feel safer(规范比较级)"}, {"q": "7", "answer": "D", "options": ["herself", "themselves", "himself", "myself"], "explanation": "自己关灯 by myself"}, {"q": "8", "answer": "B", "options": ["no", "any", "some", "much"], "explanation": "not...any more 不再"}, {"q": "9", "answer": "A", "options": ["taught", "gave", "told", "bought"], "explanation": "教了我一课 taught me a lesson"}, {"q": "10", "answer": "C", "options": ["new", "long", "real", "big"], "explanation": "恐惧并不真实 not real"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U4', 'The Quiet Girl', 'Lucy used to be a very (1)____ girl. She didn''t use to talk to anyone in class, and she always sat (2)____ in the corner. Her classmates thought she was unfriendly, but the (3)____ was that she was just shy. Everything changed when a new teacher (4)____ her to join the school play. At first, Lucy was (5)____ and wanted to say no. But the teacher encouraged her, so she (6)____ to try. During the weeks of practice, she made many (7)____. They helped her feel more confident. On the night of the show, Lucy spoke (8)____ and clearly in front of everyone. Her parents were so (9)____ of her. Now Lucy is one of the most active students in school. She is no longer the quiet girl she (10)____ to be.', 132, 3, '[{"q": "1", "answer": "B", "options": ["tall", "quiet", "funny", "loud"], "explanation": "曾经内向 quiet"}, {"q": "2", "answer": "B", "options": ["together", "alone", "happily", "quickly"], "explanation": "独自坐角落 sat alone"}, {"q": "3", "answer": "A", "options": ["truth", "idea", "story", "problem"], "explanation": "事实是 the truth was"}, {"q": "4", "answer": "A", "options": ["asked", "refused", "forgot", "stopped"], "explanation": "老师叫她参加 asked her to join"}, {"q": "5", "answer": "A", "options": ["nervous", "excited", "angry", "tired"], "explanation": "紧张想拒绝 nervous"}, {"q": "6", "answer": "D", "options": ["failed", "forgot", "refused", "decided"], "explanation": "决定试试 decided to try"}, {"q": "7", "answer": "D", "options": ["mistakes", "photos", "plans", "friends"], "explanation": "交了朋友 made many friends"}, {"q": "8", "answer": "C", "options": ["quietly", "slowly", "loudly", "badly"], "explanation": "大声清楚地说 spoke loudly"}, {"q": "9", "answer": "B", "options": ["afraid", "proud", "bored", "tired"], "explanation": "为她骄傲 proud of her"}, {"q": "10", "answer": "C", "options": ["liked", "had", "used", "wanted"], "explanation": "她曾经的样子 used to be"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U4', 'My Grandfather''s Stories', 'My grandfather is eighty years old now, but he (1)____ to be a strong young farmer. He often tells me about his (2)____. When he was young, there were no phones or computers. People used to (3)____ letters to keep in touch. Life was (4)____ then, but he says it was also peaceful. Every morning, he used to (5)____ up before the sun and work in the fields. In the evening, the whole family would (6)____ around the table and share stories. "We didn''t have much (7)____," he says, "but we were happy." I love listening to him because his stories help me (8)____ how much the world has changed. Sometimes I wish I (9)____ see the village he grew up in. His memories are like a (10)____ to the past.', 131, 3, '[{"q": "1", "answer": "B", "options": ["wanted", "used", "liked", "had"], "explanation": "曾经是 used to be"}, {"q": "2", "answer": "B", "options": ["future", "past", "city", "school"], "explanation": "讲他的过去 his past"}, {"q": "3", "answer": "A", "options": ["write", "buy", "sell", "read"], "explanation": "写信 write letters"}, {"q": "4", "answer": "C", "options": ["easier", "shorter", "harder", "richer"], "explanation": "生活更艰苦 harder"}, {"q": "5", "answer": "B", "options": ["put", "get", "look", "take"], "explanation": "起床 get up"}, {"q": "6", "answer": "C", "options": ["jump", "run", "sit", "stand"], "explanation": "围坐桌旁 sit around the table"}, {"q": "7", "answer": "D", "options": ["water", "food", "time", "money"], "explanation": "没多少钱 not much money"}, {"q": "8", "answer": "A", "options": ["understand", "forget", "leave", "refuse"], "explanation": "帮我理解 understand"}, {"q": "9", "answer": "D", "options": ["should", "need", "must", "could"], "explanation": "但愿我能 wish I could"}, {"q": "10", "answer": "A", "options": ["window", "map", "key", "door"], "explanation": "通往过去的窗 a window to the past"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U4', 'Learning to Swim', 'I used to be afraid of (1)____. When I was younger, I wouldn''t even put my face in the pool. My friends could all swim, but I always sat by the (2)____ and watched. I felt (3)____ that I was the only one who couldn''t. One summer, my aunt offered to (4)____ me. She was very patient. "Don''t be afraid," she said. "I will (5)____ you the whole time." At first, I only put my feet in the water. Then, little by little, I learned to (6)____ my breath and float. It took many (7)____, but I didn''t give up. By the end of the summer, I could swim across the whole pool! I felt so (8)____ of myself. Now I love swimming, and I can hardly believe I (9)____ to be scared of it. The water that once frightened me is now my favorite (10)____.', 146, 3, '[{"q": "1", "answer": "C", "options": ["heights", "dogs", "water", "fire"], "explanation": "怕水 afraid of water"}, {"q": "2", "answer": "C", "options": ["wall", "door", "pool", "tree"], "explanation": "坐在泳池边 by the pool"}, {"q": "3", "answer": "D", "options": ["proud", "glad", "brave", "bad"], "explanation": "感觉很糟 felt bad"}, {"q": "4", "answer": "B", "options": ["buy", "teach", "leave", "watch"], "explanation": "教我 teach me"}, {"q": "5", "answer": "B", "options": ["stop", "support", "sell", "lose"], "explanation": "[填空] 我会一直扶着你 support you the whole time"}, {"q": "6", "answer": "B", "options": ["catch", "hold", "cut", "throw"], "explanation": "屏住呼吸 hold my breath"}, {"q": "7", "answer": "A", "options": ["weeks", "games", "books", "photos"], "explanation": "花了好几周 many weeks"}, {"q": "8", "answer": "D", "options": ["afraid", "sorry", "tired", "proud"], "explanation": "为自己自豪 proud"}, {"q": "9", "answer": "A", "options": ["used", "wanted", "liked", "had"], "explanation": "曾经怕 used to be scared"}, {"q": "10", "answer": "A", "options": ["place", "time", "day", "way"], "explanation": "最爱的地方 favorite place"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U4', 'The Old Photo', 'Last weekend, I found an old (1)____ in a drawer. It showed my mother when she was a (2)____ girl. I was surprised because she looked so (3)____ from now. In the photo, she used to have long curly hair, but today her hair is short and (4)____. She used to wear glasses too, but now she doesn''t. I showed the photo to her, and she (5)____. "I remember that day," she said. "I used to be very shy back then. I didn''t use to (6)____ to strangers at all." It was hard to (7)____, because now she talks to everyone easily. She told me that people can (8)____ a lot over the years. Looking at the photo made me (9)____ about how I might change in the future too. I carefully put the photo (10)____ in the drawer to keep it safe.', 143, 3, '[{"q": "1", "answer": "A", "options": ["photo", "book", "letter", "map"], "explanation": "老照片 old photo"}, {"q": "2", "answer": "A", "options": ["young", "old", "tall", "new"], "explanation": "年轻女孩 young girl"}, {"q": "3", "answer": "D", "options": ["easy", "busy", "same", "different"], "explanation": "看起来不同 different from now"}, {"q": "4", "answer": "D", "options": ["long", "curly", "white", "straight"], "explanation": "短而直 short and straight"}, {"q": "5", "answer": "A", "options": ["smiled", "slept", "cried", "ran"], "explanation": "她笑了 smiled"}, {"q": "6", "answer": "B", "options": ["sit", "talk", "look", "walk"], "explanation": "不跟陌生人说话 talk to strangers"}, {"q": "7", "answer": "B", "options": ["refuse", "believe", "forget", "leave"], "explanation": "难以相信 hard to believe"}, {"q": "8", "answer": "B", "options": ["sell", "change", "stop", "lose"], "explanation": "会变很多 change a lot"}, {"q": "9", "answer": "C", "options": ["stop", "forget", "think", "refuse"], "explanation": "让我思考 made me think"}, {"q": "10", "answer": "C", "options": ["off", "out", "back", "away"], "explanation": "放回抽屉 put it back"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U4', 'From Lazy to Hard-working', 'Tom didn''t use to be a good (1)____. In the past, he never finished his homework on (2)____, and he often fell asleep in class. His grades were (3)____, and his teachers were worried about him. Then, in Grade 8, something (4)____. His class had a new science teacher who made every lesson fun and (5)____. For the first time, Tom felt interested in (6)____. He started to study harder and ask questions. Slowly, his grades got (7)____. His parents could hardly (8)____ the change in him. "You used to hate studying," his mother said, "but now you can''t (9)____ reading your books!" Tom just smiled. He had learned that the right teacher and a little effort can (10)____ everything. He is no longer the lazy boy he used to be.', 131, 3, '[{"q": "1", "answer": "D", "options": ["driver", "cook", "teacher", "student"], "explanation": "好学生 good student"}, {"q": "2", "answer": "A", "options": ["time", "sale", "foot", "fire"], "explanation": "按时 on time"}, {"q": "3", "answer": "A", "options": ["poor", "great", "high", "good"], "explanation": "成绩差 poor"}, {"q": "4", "answer": "C", "options": ["opened", "stopped", "changed", "closed"], "explanation": "有事发生改变 something changed"}, {"q": "5", "answer": "A", "options": ["interesting", "difficult", "short", "boring"], "explanation": "有趣 fun and interesting"}, {"q": "6", "answer": "B", "options": ["playing", "learning", "eating", "sleeping"], "explanation": "对学习感兴趣 interested in learning"}, {"q": "7", "answer": "B", "options": ["worse", "better", "less", "fewer"], "explanation": "成绩变好 got better"}, {"q": "8", "answer": "B", "options": ["lose", "believe", "refuse", "forget"], "explanation": "难以相信变化 hardly believe"}, {"q": "9", "answer": "C", "options": ["begin", "keep", "stop", "start"], "explanation": "停不下来读书 can''t stop reading"}, {"q": "10", "answer": "D", "options": ["buy", "sell", "lose", "change"], "explanation": "能改变一切 change everything"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U4 听力·对话 Meeting an Old Classmate', '九年级 Unit4 听力·成长变化(used to)', 2, 'Emma: Wow, Jack, is that really you? You used to be so short!
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U4 听力·短文 How I Have Changed', '九年级 Unit4 听力·成长变化(used to)', 2, 'Hello, I''m Sarah, and I want to share how I have changed. When I was younger, I used to be afraid of speaking in public. My voice would shake and I would forget my words. I didn''t use to put up my hand in class at all. But in Grade 7, my teacher asked me to read a short story to the class. I was so nervous, but everyone clapped afterwards. That moment gave me confidence. Now I am the host of our school radio show, and I speak to hundreds of students every week. I never thought I could change so much.', '大家好,我是Sarah,想分享我的变化。小时候我很怕当众讲话,声音会发抖,还会忘词。我以前在课上根本不举手。但七年级时,老师让我给全班读一个小故事。我特别紧张,但读完大家都鼓掌了。那一刻给了我信心。现在我是学校广播节目的主持人,每周对几百名学生讲话。我从没想过自己能变这么多。', 'us_female', '[{"q": "What did Sarah use to be afraid of?", "type": "choice", "answer": "B", "options": ["Animals.", "Speaking in public.", "Tests.", "The dark."]}, {"q": "What did she NOT use to do in class?", "type": "choice", "answer": "A", "options": ["Put up her hand.", "Sit down.", "Take notes.", "Listen."]}, {"q": "What did her teacher ask her to do in Grade 7?", "type": "choice", "answer": "B", "options": ["Sing a song.", "Read a short story to the class.", "Write an essay.", "Lead a game."]}, {"q": "What is Sarah''s role now?", "type": "choice", "answer": "A", "options": ["Host of the school radio show.", "A class monitor.", "A drama actor.", "A sports captain."]}, {"q": "What is the main message of Sarah''s talk?", "type": "choice", "answer": "A", "options": ["She has changed a lot and gained confidence.", "She loves the radio.", "School is difficult.", "Reading is boring."]}]'::jsonb, '[]'::jsonb, 'short', '9', 'U4');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U4 听力·对话 Talking About Old Fears', '九年级 Unit4 听力·成长变化(used to)', 2, 'Ben: Lily, were you ever afraid of anything when you were little?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U4 听力·短文 My Cousin Mike', '九年级 Unit4 听力·成长变化(used to)', 2, 'Let me tell you about my cousin, Mike. A few years ago, he used to be a chubby boy with glasses. He didn''t use to do any sports, and he spent most of his time playing computer games. But last year, something changed. He started running every morning and joined the school swimming team. Now he is fit and strong, and he doesn''t wear glasses anymore because he had an eye operation. He also used to be quite shy, but now he has many friends. The biggest change is that he is much happier and more active than before.', '我来说说我表哥Mike。几年前,他是个戴眼镜的胖男孩。他以前不做任何运动,大部分时间打电脑游戏。但去年有了变化。他开始每天早上跑步,还加入了学校游泳队。现在他健康强壮,也不再戴眼镜了,因为做了眼睛手术。他以前还挺害羞,现在朋友很多。最大的变化是他比以前快乐、活跃多了。', 'us_female', '[{"q": "What did Mike use to look like?", "type": "choice", "answer": "D", "options": ["A boy with curly hair.", "A tall thin boy.", "A short boy with short hair.", "A chubby boy with glasses."]}, {"q": "What did Mike NOT use to do?", "type": "choice", "answer": "D", "options": ["Sleeping.", "Eating.", "Computer games.", "Any sports."]}, {"q": "What did Mike do to change?", "type": "choice", "answer": "B", "options": ["Got a pet.", "Started running and joined the swimming team.", "Started reading.", "Moved to a new school."]}, {"q": "Why doesn''t Mike wear glasses now?", "type": "choice", "answer": "D", "options": ["He never needed them.", "He bought contact lenses.", "He lost them.", "He had an eye operation."]}, {"q": "What is the biggest change in Mike?", "type": "choice", "answer": "C", "options": ["He is quieter.", "He is richer.", "He is happier and more active.", "He is taller."]}]'::jsonb, '[]'::jsonb, 'short', '9', 'U4');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U4 听力·短文 Life in the Old Days', '九年级 Unit4 听力·成长变化(used to)', 2, 'When I was a child, life used to be very different. We didn''t use to have televisions or mobile phones. In the evenings, my family used to sit together and tell stories. We used to grow our own vegetables in the garden. There used to be a big tree in front of our house, and I would climb it every day. School was far away, so we used to walk for an hour to get there. Things were harder then, but we were close to nature and to each other. I sometimes miss those simple days.', '我小时候,生活和现在很不一样。我们以前没有电视和手机。晚上,一家人会坐在一起讲故事。我们以前自己在园子里种菜。我家门前以前有棵大树,我每天都爬。学校很远,所以我们以前要走一小时去上学。那时生活更艰苦,但我们亲近自然、彼此亲密。我有时会怀念那些简单的日子。', 'us_female', '[{"q": "What did the speaker''s family NOT use to have?", "type": "choice", "answer": "B", "options": ["A house.", "Televisions or mobile phones.", "A garden.", "A big tree."]}, {"q": "What did the family use to do in the evenings?", "type": "choice", "answer": "D", "options": ["Play games.", "Go shopping.", "Watch TV.", "Sit together and tell stories."]}, {"q": "What used to be in front of their house?", "type": "choice", "answer": "A", "options": ["A big tree.", "A river.", "A garden.", "A small shop."]}, {"q": "How did they use to get to school?", "type": "choice", "answer": "B", "options": ["Drive a car.", "Walk for an hour.", "Ride a bike.", "Take a bus."]}, {"q": "How does the speaker feel about the past?", "type": "choice", "answer": "C", "options": ["She felt bored.", "She is glad they ended.", "She misses those simple days.", "She has no feeling."]}]'::jsonb, '[]'::jsonb, 'short', '9', 'U4');
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U4 听力·对话 Sharing How We Have Changed', '九年级 Unit4 听力·成长变化(used to)', 2, 'Teacher: Today, let''s share how we have changed. Tony, would you like to start?
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'How I Have Changed', '每个人都在成长中改变。请以 "How I Have Changed" 为题,写一篇约80词的短文,描述你和过去相比的变化。', 'Write a short passage on the topic: "How I Have Changed".', '["你过去是什么样(外貌/性格/习惯,至少两点,用 used to)", "你现在是什么样", "是什么让你改变的", "你对这个变化的感受"]'::jsonb, 70, 100, 'I have changed a lot in the past few years. I used to be a short and shy boy. I didn''t use to talk to new people, and I was even afraid of speaking in class. But now I am taller and much more confident. Joining the school basketball team helped me change. I made many friends and learned to believe in myself. I''m really happy that I am not the shy child I used to be.', 'content:涵盖4个要点(过去样子≥2点/现在/原因/感受)；language:正确使用 used to / didn''t use to;时态过去与现在对比清晰；structure:条理清晰、句子连贯；wordcount:约80词', 3, 'How I Have Changed', '["I used to be / used to + 动词原形", "I didn''t use to ...", "but now ...", "... helped me change", "I''m happy that I have changed"]'::jsonb, '[]'::jsonb, '要点:你过去是什么样(外貌/性格/习惯,至少两点,用 used to)；你现在是什么样；是什么让你改变的；你对这个变化的感受', '9', 'U4' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U4' AND topic='How I Have Changed');
